{
  "name": "Network Deployment Workflow",
  "description": "Automated network provisioning and configuration",
  "tasks": [
    {
      "id": "validate_config",
      "name": "Validate Configuration",
      "type": "validation",
      "action": "{\"type\": \"condition\", \"conditions\": [{\"field\": \"network_cidr\", \"operator\": \"exists\"}]}"
    },
    {
      "id": "provision_network",
      "name": "Provision Network",
      "type": "network_provision",
      "dependencies": ["validate_config"],
      "action": "{\"network_type\": \"production\", \"auto_start\": true}"
    }
  ],
  "enabled": true
}

{
  "request": "Create a development network with 3 web servers, 1 database server, and a load balancer. Use 192.168.100.0/24 subnet.",
  "context": {
    "environment": "development",
    "region": "us-west-2"
  }
}
